<script lang="ts">import{bubbleContentClassName}from'@fex-design/styles/bubble';import{cn}from'@fex/utils';import{getContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{bubbleContextKey,type BubbleContextValue}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{children?:Snippet;render?:Snippet<[{props:Record<string,unknown>;state:Record<string,unknown>}]>}let{class:className,children,render,...rest}:Props=$props();const context=getContext<BubbleContextValue|undefined>(bubbleContextKey);let state=$derived({side:context?.side()??'start',size:context?.size()??'md',variant:context?.variant()??'soft'});let binding=$derived({...rest,'data-slot':'bubble-content','data-side':state.side,class:cn(bubbleContentClassName({size:state.size,variant:state.variant}),className)})</script>
{#if render}{@render render({props:binding,state})}{:else}<div {...binding}>{@render children?.()}</div>{/if}
